def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters in the message are represented in the mapping, the function
    returns "Failed".

    Args:
        encoded (str): A string representing the encoded information.
        original (str): A string representing the original information corresponding to the encoded string.
        message (str): A string representing the encrypted message to be decoded.

    Returns:
        str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    char_map = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in char_map:
            if char_map[e_char] != o_char:
                return "Failed"
        else:
            char_map[e_char] = o_char

    decoded_chars = []
    for m_char in message:
        if m_char not in char_map:
            return "Failed"
        decoded_chars.append(char_map[m_char])

    return "".join(decoded_chars)

def is_prime(num: int) -> bool:
    """Determine whether an integer is a prime number.

    Uses the 6k ± 1 optimization to test divisibility up to sqrt(num).

    Args:
        num: The integer to check for primality.

    Returns:
        True if `num` is prime, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False

    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Parameters:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    # Build a mapping from digit to list of possible replacements
    mapping = {}
    for x, y in rules:
        mapping.setdefault(str(x), set()).add(str(y))

    start = str(n)
    visited = {int(start)}
    queue = [start]

    while queue:
        current_str = queue.pop(0)
        for idx, ch in enumerate(current_str):
            if ch in mapping:
                for new_digit in mapping[ch]:
                    new_num_str = current_str[:idx] + new_digit + current_str[idx + 1 :]
                    new_num = int(new_num_str)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num_str)

    return len(visited)

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += catalan[j] * catalan[i - 1 - j]
        catalan[i] = total
    return catalan[n]

def min_remaining_space(V: int, n: int, volumes: list[int]) -> int:
    """Return the minimum remaining space in a box of size V after packing a subset of n items."""
    # Limit the list to the first n items
    volumes = volumes[:n]
    # DP array: dp[c] is True if capacity c can be achieved
    dp = [False] * (V + 1)
    dp[0] = True
    best = 0
    for vol in volumes:
        if vol > V:
            continue
        # Go backwards to avoid reuse of the same item
        for c in range(V, vol - 1, -1):
            if dp[c - vol]:
                dp[c] = True
                if c > best:
                    best = c
    return V - best
