def mod_inverse(a, b):
    # Extended Euclidean Algorithm
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        gcd, x1, y1 = extended_gcd(y, x % y)
        return (gcd, y1, x1 - (x // y) * y1)

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    return x % b

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    max_bitonic = 0
    for i in range(n):
        # subtract 1 to avoid double counting the peak student
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - 1)

    return n - max_bitonic
